static bool HandleGameObjectTargetCommand(ChatHandler* handler, char const* args)
{
    Player* player = handler->GetSession()->GetPlayer();
    QueryResult result;
    GameEventMgr::ActiveEvents const& activeEventsList = sGameEventMgr->GetActiveEventList();

    if (*args)
    {
        // number or [name] Shift-click form |color|Hgameobject_entry:go_id|h[name]|h|r
        char* id = handler->extractKeyFromLink((char*)args, "Hgameobject_entry");
        if (!id)
            return false;

        uint32 objectId = 0;
        if (isNumeric(id) && !Trinity::ParseCommandInteger(id, objectId))
            return false;

        if (objectId)
            result = WorldDatabase.PQuery("SELECT guid, id, position_x, position_y, position_z, orientation, map, phaseMask, (POW(position_x - '%f', 2) + POW(position_y - '%f', 2) + POW(position_z - '%f', 2)) AS order_ FROM gameobject WHERE map = '%i' AND id = '%u' ORDER BY order_ ASC LIMIT 1",
            player->GetPositionX(), player->GetPositionY(), player->GetPositionZ(), player->GetMapId(), objectId);
        else
        {
            std::string name = id;
            WorldDatabase.EscapeString(name);
            result = WorldDatabase.PQuery(
                "SELECT guid, id, position_x, position_y, position_z, orientation, map, phaseMask, (POW(position_x - %f, 2) + POW(position_y - %f, 2) + POW(position_z - %f, 2)) AS order_ "
                "FROM gameobject, gameobject_template WHERE gameobject_template.entry = gameobject.id AND map = %i AND name LIKE '%%%s%%' ORDER BY order_ ASC LIMIT 1",
                player->GetPositionX(), player->GetPositionY(), player->GetPositionZ(), player->GetMapId(), name.c_str());
        }
    }
    else
    {
        std::ostringstream eventFilter;
        eventFilter << " AND (eventEntry IS NULL ";
        bool initString = true;

        for (GameEventMgr::ActiveEvents::const_iterator itr = activeEventsList.begin(); itr != activeEventsList.end(); ++itr)
        {
            if (initString)
            {
                eventFilter  <<  "OR eventEntry IN (" << *itr;
                initString = false;
            }
            else
                eventFilter << ',' << *itr;
        }

        if (!initString)
            eventFilter << "))";
        else
            eventFilter << ')';

        result = WorldDatabase.PQuery("SELECT gameobject.guid, id, position_x, position_y, position_z, orientation, map, phaseMask, "
            "(POW(position_x - %f, 2) + POW(position_y - %f, 2) + POW(position_z - %f, 2)) AS order_ FROM gameobject "
            "LEFT OUTER JOIN game_event_gameobject on gameobject.guid = game_event_gameobject.guid WHERE map = '%i' %s ORDER BY order_ ASC LIMIT 10",
            handler->GetSession()->GetPlayer()->GetPositionX(), handler->GetSession()->GetPlayer()->GetPositionY(), handler->GetSession()->GetPlayer()->GetPositionZ(),
            handler->GetSession()->GetPlayer()->GetMapId(), eventFilter.str().c_str());
    }

    if (!result)
    {
        handler->SendSysMessage(LANG_COMMAND_TARGETOBJNOTFOUND);
        return true;
    }

    bool found = false;
    float x, y, z, o;
    uint32 guidLow;
    uint32 id;
    uint16 mapId, phase;
    uint32 poolId;

    do
    {
        Field* fields = result->Fetch();
        guidLow = fields[0].GetUInt64();
        id =      fields[1].GetUInt32();
        x =       fields[2].GetFloat();
        y =       fields[3].GetFloat();
        z =       fields[4].GetFloat();
        o =       fields[5].GetFloat();
        mapId =   fields[6].GetUInt16();
        phase =   fields[7].GetUInt16();
        poolId =  sPoolMgr->IsPartOfAPool<GameObject>(guidLow);
        if (!poolId || sPoolMgr->IsSpawnedObject<GameObject>(guidLow))
            found = true;
    } while (result->NextRow() && !found);

    if (!found)
    {
        handler->PSendSysMessage(LANG_GAMEOBJECT_NOT_EXIST, id);
        return false;
    }

    GameObjectTemplate const* objectInfo = sObjectMgr->GetGameObjectTemplate(id);

    if (!objectInfo)
    {
        handler->PSendSysMessage(LANG_GAMEOBJECT_NOT_EXIST, id);
        return false;
    }

    GameObject* target = handler->GetSession()->GetPlayer()->GetMap()->GetGameObject(ObjectGuid::Create<HighGuid::GameObject>(mapId, id, guidLow));

    handler->PSendSysMessage(LANG_GAMEOBJECT_DETAIL, guidLow, objectInfo->name.c_str(), guidLow, id, x, y, z, mapId, o, phase);
    player->SetLastTargetedGO(guidLow);

    if (target)
    {
        int32 curRespawnDelay = int32(target->GetRespawnTimeEx() - GameTime::GetGameTime());
        if (curRespawnDelay < 0)
            curRespawnDelay = 0;

        std::string curRespawnDelayStr = secsToTimeString(curRespawnDelay, true);
        std::string defRespawnDelayStr = secsToTimeString(target->GetRespawnDelay(), true);

        handler->PSendSysMessage(LANG_COMMAND_RAWPAWNTIMES, defRespawnDelayStr.c_str(), curRespawnDelayStr.c_str());
    }
    return true;
}

changes.old:
static bool HandleDebugSendSpellFailCommand(ChatHandler* handler, char const* args)
{
    if (!*args)
        return false;

    char* result = strtok((char*)args, " ");
    if (!result)
        return false;

    uint8 failNum = (uint8)atoi(result);
    if (failNum == 0 && *result != '0')
        return false;

    char* fail1 = strtok(NULL, " ");
    uint8 failArg1 = fail1 ? (uint8)atoi(fail1) : 0;

    char* fail2 = strtok(NULL, " ");
    uint8 failArg2 = fail2 ? (uint8)atoi(fail2) : 0;

    WorldPacket data(SMSG_CAST_FAILED, 5);
    data.WriteBit(!failArg2);
    data.WriteBit(!failArg1);
    data << uint32(failNum);                                // problem
    data << uint32(133);                                    // spellId
    if (failArg2)
        data << uint32(failArg2);
    data << uint8(0);                                       // single cast or multi 2.3 (0/1)
    if (failArg1)
        data << uint32(failArg2);

    if (Player* player = handler->GetSession()->GetPlayer())
        player->SendDirectMessage(&data);

    return true;
}

changes.new:
static bool HandleDebugSendSpellFailCommand(ChatHandler* handler, char const* args)
{
    if (!*args)
        return false;

    char* result = strtok((char*)args, " ");
    if (!result)
        return false;

    int32 failNum;
    if (!Trinity::ParseCommandInteger(result, failNum) || failNum < 0 || failNum > SPELL_FAILED_UNKNOWN)
        return false;
    char* fail1 = strtok(nullptr, " ");
    char* fail2 = strtok(nullptr, " ");
    int32 failArg1 = -1, failArg2 = -1;
    if ((fail1 && !Trinity::ParseCommandInteger(fail1, failArg1)) ||
        (fail2 && !Trinity::ParseCommandInteger(fail2, failArg2)))
        return false;
    Player* player = handler->GetSession()->GetPlayer();
    if (!player)
        return false;
    WorldPackets::Spells::CastFailed packet(SMSG_CAST_FAILED);
    packet.SpellID = 133;
    packet.Reason = failNum;
    packet.FailedArg1 = failArg1;
    packet.FailedArg2 = failArg2;
    player->SendDirectMessage(packet.Write());

    return true;
}

extra_edits.old:
void Player::DeleteOldCharacters(uint32 keepDays)
{
    TC_LOG_INFO("entities.player", "Player::DeleteOldChars: Deleting all characters which have been deleted %u days before...", keepDays);

    CharacterDatabasePreparedStatement* stmt = CharacterDatabase.GetPreparedStatement(CHAR_SEL_CHAR_OLD_CHARS);
    stmt->setUInt32(0, uint32(GameTime::GetGameTime() - time_t(keepDays * DAY)));
    PreparedQueryResult result = CharacterDatabase.Query(stmt);

    if (result)
    {
         TC_LOG_DEBUG("entities.player", "Player::DeleteOldChars: Found " UI64FMTD " character(s) to delete", result->GetRowCount());
         do
         {
            Field* fields = result->Fetch();
            Player::DeleteFromDB(ObjectGuid::Create<HighGuid::Player>(fields[0].GetUInt64()), fields[1].GetUInt32(), true, true);
         }
         while (result->NextRow());
    }
}

extra_edits.new:
void Player::DeleteOldCharacters(uint32 keepDays)
{
    TC_LOG_INFO("entities.player", "Player::DeleteOldChars: Deleting all characters which have been deleted %u days before...", keepDays);

    time_t now = GameTime::GetGameTime();
    uint64 retention = uint64(keepDays) * DAY;
    if (now <= 0 || retention >= uint64(now))
        return;

    CharacterDatabasePreparedStatement* stmt = CharacterDatabase.GetPreparedStatement(CHAR_SEL_CHAR_OLD_CHARS);
    stmt->setUInt64(0, uint64(now) - retention);
    PreparedQueryResult result = CharacterDatabase.Query(stmt);

    if (result)
    {
         TC_LOG_DEBUG("entities.player", "Player::DeleteOldChars: Found " UI64FMTD " character(s) to delete", result->GetRowCount());
         do
         {
            Field* fields = result->Fetch();
            Player::DeleteFromDB(ObjectGuid::Create<HighGuid::Player>(fields[0].GetUInt64()), fields[1].GetUInt32(), true, true);
         }
         while (result->NextRow());
    }
}
